package com.company.logicdelete.starter;
import com.company.logicdelete.runtime.*;import org.apache.ibatis.plugin.Interceptor;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.*;import org.springframework.boot.web.servlet.FilterRegistrationBean;
@Configuration(proxyBeanMethods=false)@ConditionalOnClass(Interceptor.class)@ConditionalOnProperty(prefix="logic-delete.runtime",name="enabled",havingValue="true")@EnableConfigurationProperties(SpringRuntimeTraceProperties.class)
public class LogicDeleteRuntimeAutoConfiguration {@Bean@ConditionalOnMissingBean RuntimeSqlEventReporter logicDeleteReporter(SpringRuntimeTraceProperties p){return new FileRuntimeSqlEventReporter(p.getOutputPath());}@Bean@ConditionalOnMissingBean LogicDeleteSqlTraceInterceptor logicDeleteInterceptor(SpringRuntimeTraceProperties p,RuntimeSqlEventReporter r){return new LogicDeleteSqlTraceInterceptor(p,r);}@Bean@ConditionalOnWebApplication@ConditionalOnProperty(prefix="logic-delete.runtime",name="collect-http-entry",havingValue="true",matchIfMissing=true)FilterRegistrationBean<LogicDeleteHttpFilter> logicDeleteFilter(SpringRuntimeTraceProperties p){FilterRegistrationBean<LogicDeleteHttpFilter>b=new FilterRegistrationBean<>();b.setFilter(new LogicDeleteHttpFilter(p));b.setOrder(Integer.MIN_VALUE+100);return b;}}
